        thermal_relief_gap: Nm::from_mm(0.2),          // 8 mil
        thermal_relief_spoke_width: Nm::from_mm(0.3),  // 12 mil (wider for reliability)
        min_copper_pour_clearance: Nm::from_mm(0.2),   // 8 mil
